class Solution {
public:
    bool canDivideIntoSubsequences(vector<int>& nums, int k) {
        int maximum = 0;
        int run = 0;
        for (int i = 0; i < static_cast<int>(nums.size()); ++i) {
            if (i > 0 && nums[i] == nums[i - 1]) {
                ++run;
            } else {
                run = 1;
            }
            maximum = max(maximum, run);
        }
        return static_cast<long long>(maximum) * k <= nums.size();
    }
};
